using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

var vaultUri = new Uri("https://my-vault.vault.azure.net/");
var client = new SecretClient(vaultUri, new DefaultAzureCredential());

KeyVaultSecret secret = await client.GetSecretAsync("DatabaseConnectionString");
string connectionString = secret.Value;

// In production on Azure, DefaultAzureCredential picks up
// the managed identity automatically. Locally, it falls
// back to Visual Studio, Azure CLI, or environment variables.
